[Console]::OutputEncoding = [System.Text.Encoding]::UTF8; $ProgressPreference = 'SilentlyContinue'

# Helper function to handle null values and escape special characters
function HandleString($value) {
    if ($null -eq $value) { 
        return "-" 
    } else { 
        return $value -replace '"', '\"'  # Escape double quotes
    }
}

try {
    $details = @()
    $domain = HandleString((Get-ADDomainController).Forest)

    # Default Domain Password Policy
    $passwordPolicy = Get-ADDefaultDomainPasswordPolicy 
    $details += @{
        domain = $domain
        name = "Default Domain Policy"
        complexityenabled = $passwordPolicy.ComplexityEnabled
        distinguishedname = HandleString($passwordPolicy.DistinguishedName)
        lockoutduration = [String]$passwordPolicy.lockoutDuration
        lockoutobservationwindow = [String]$passwordPolicy.LockoutObservationWindow
        lockoutthreshold = [String]$passwordPolicy.LockoutThreshold
        objectguid = HandleString([String]$passwordPolicy.ObjectGuid)
        maxpwdage = $passwordPolicy.MaxPasswordAge.Days
        minpwdage = $passwordPolicy.MinPasswordAge.Days
        minpwdlength = $passwordPolicy.MinPasswordLength
        pwdhistorylength = $passwordPolicy.PasswordHistoryCount
        reversibleencryptionenabled = $passwordPolicy.reversibleEncryptionEnabled
    }

    # Fine-Grained Password Policies
    $ADFineGrainedPasswordPolicy = Get-ADFineGrainedPasswordPolicy -Filter *
    if ($ADFineGrainedPasswordPolicy) {
        foreach ($o in $ADFineGrainedPasswordPolicy) {
            $details += @{
                domain = $domain
                name = HandleString($o.Name)
                complexityenabled = $o.ComplexityEnabled
                distinguishedname = HandleString($o.DistinguishedName)
                lockoutduration = [String]$o.lockoutDuration
                lockoutobservationwindow = [String]$o.LockoutObservationWindow
                lockoutthreshold = [String]$o.LockoutThreshold
                maxpwdage = $o.MaxPasswordAge.Days
                objectguid = HandleString([String]$o.ObjectGuid)
                minpwdage = $o.MinPasswordAge.Days
                minpwdlength = $o.MinPasswordLength
                pwdhistorylength = $o.PasswordHistoryCount
                reversibleencryptionenabled = $o.reversibleEncryptionEnabled
            }
        }
    }

    # Convert details to JSON with proper depth
    ConvertTo-Json -Depth 5 -Compress @{
        status = $true
        data = $details
    }
}
catch {
    ConvertTo-Json -Depth 5 -Compress @{
        status = $false
        msg = $( $_.Exception.Message )
        stackTrace = $_ | Out-String
    }
}
